PRAGMA foreign_keys=OFF;
DROP TABLE IF EXISTS audit_events; DROP TABLE IF EXISTS reports; DROP TABLE IF EXISTS read_cursors; DROP TABLE IF EXISTS presence; DROP TABLE IF EXISTS receipts; DROP TABLE IF EXISTS realtime_events; DROP TABLE IF EXISTS link_previews; DROP TABLE IF EXISTS attachments; DROP TABLE IF EXISTS direct_messages; DROP TABLE IF EXISTS direct_participants; DROP TABLE IF EXISTS direct_threads; DROP TABLE IF EXISTS messages; DROP TABLE IF EXISTS channel_members; DROP TABLE IF EXISTS invitations; DROP TABLE IF EXISTS channels; DROP TABLE IF EXISTS workspace_members; DROP TABLE IF EXISTS workspaces; DROP TABLE IF EXISTS sessions; DROP TABLE IF EXISTS users;
PRAGMA foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,global_role TEXT NOT NULL DEFAULT 'member',status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE workspaces(id INTEGER PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE workspace_members(workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',PRIMARY KEY(workspace_id,user_id));
CREATE TABLE channels(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name TEXT NOT NULL,visibility TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,name));
CREATE TABLE invitations(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,email TEXT NOT NULL,role TEXT NOT NULL,token TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'pending',expires_at TEXT NOT NULL,UNIQUE(workspace_id,email,status));
CREATE TABLE channel_members(channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL DEFAULT 'member',PRIMARY KEY(channel_id,user_id));
CREATE TABLE messages(id INTEGER PRIMARY KEY,channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE CASCADE,author_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT,idempotency_key TEXT UNIQUE NOT NULL);
CREATE TABLE direct_threads(id INTEGER PRIMARY KEY,created_at TEXT NOT NULL,participant_key TEXT UNIQUE NOT NULL);
CREATE TABLE direct_participants(thread_id INTEGER NOT NULL REFERENCES direct_threads(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(thread_id,user_id));
CREATE TABLE direct_messages(id INTEGER PRIMARY KEY,thread_id INTEGER NOT NULL REFERENCES direct_threads(id) ON DELETE CASCADE,author_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL);
CREATE TABLE attachments(id INTEGER PRIMARY KEY,channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE CASCADE,uploader_id INTEGER NOT NULL REFERENCES users(id),filename TEXT NOT NULL,content_type TEXT NOT NULL,content BLOB NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE link_previews(id INTEGER PRIMARY KEY,message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE,url TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(message_id,url));
CREATE TABLE realtime_events(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,event_type TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE receipts(message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,delivered_at TEXT NOT NULL,PRIMARY KEY(message_id,user_id));
CREATE TABLE presence(workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,state TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(workspace_id,user_id));
CREATE TABLE read_cursors(channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,message_id INTEGER NOT NULL REFERENCES messages(id),updated_at TEXT NOT NULL,PRIMARY KEY(channel_id,user_id));
CREATE TABLE reports(id INTEGER PRIMARY KEY,message_id INTEGER NOT NULL REFERENCES messages(id),reporter_id INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',resolution_note TEXT,created_at TEXT NOT NULL,UNIQUE(message_id,reporter_id));
CREATE TABLE audit_events(id INTEGER PRIMARY KEY,workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,actor_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
